using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using KianaPet;
class SkinShuffleTests {
 static int checks;static List<string> names=new List<string>();
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;names.Add(name);}
 static object Field(object obj,string key){return obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
 static void Set(object obj,string key,object value){obj.GetType().GetField(key,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,value);}
 static object Call(object obj,string key,params object[] args){return obj.GetType().GetMethod(key,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
 [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct NativeRect{public int Left,Top,Right,Bottom;}
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr handle,out NativeRect rect);
 static string Bounds(IntPtr handle){NativeRect rect;GetWindowRect(handle,out rect);return rect.Left+","+rect.Top+","+rect.Right+","+rect.Bottom;}
 static void Planner(){
  var c=new Config();c.Validate();Check(c.SkinShuffleEnabled&&!c.SkinShuffleOnStart&&c.SkinShuffleMinutes==120&&c.SkinShuffleJitter,"two-hour timed default with optional startup");Check(c.SkinShufflePool.Length==3&&c.SkinShufflePool.All(MusicSprites.Supported),"only three Q outfits in default pool");
  c.SkinShufflePool=new[]{"invalid",null,SkinShuffleRules.Defaults[0],SkinShuffleRules.Defaults[0]};c.SkinShuffleMinutes=0;c.Validate();Check(c.SkinShufflePool.Length==1&&c.SkinShuffleMinutes==1,"candidate normalization and minimum interval");c.SkinShufflePool=new string[0];c.SkinShuffleMinutes=2000;c.Validate();Check(c.SkinShufflePool.Length==0&&c.SkinShuffleMinutes==1440,"empty pool stays intentionally empty and interval is bounded");
  var day=new DateTime(2026,11,15);c=new Config{SkinShuffleMinutes=1,SkinShuffleJitter=false};c.Validate();var p=new SkinShufflePlanner(new Random(17));p.Load(null,c);p.Advance(c,0,true,day);for(int i=1;i<=20;i++)p.Advance(c,i,true,day);Check(p.Session.Remaining==40,"count actual visible awake ticks");p.Advance(c,21,false,day);p.Advance(c,3600,false,day);p.Advance(c,3601,true,day);Check(p.Session.Remaining==40,"hidden and first return tick do not count");p.Advance(c,3602,true,day);Check(p.Session.Remaining==39,"counting resumes after visibility returns");p.Advance(c,90000,true,day);Check(p.Session.Remaining==39,"long suspension gap never catches up");for(int i=1;i<=45;i++)p.Advance(c,90000+i,true,day);Check(p.Session.Remaining==0&&p.Due(c,day),"overdue request is capped at one pending change");p.Advance(c,200000,true,day);Check(p.Session.Remaining==0,"missed intervals do not stack requests");
  p.HoldToday(day);Check(!p.Due(c,day)&&p.Held(day),"today hold overrides overdue timer");p.Advance(c,200001,true,day.AddDays(1));Check(p.Session.Remaining==60&&!p.Held(day.AddDays(1)),"next day restores full interval");p.HoldToday(day.AddDays(1));p.Manual(c);Check(p.Held(day.AddDays(1))&&p.Session.Remaining==60,"manual change resets timer while respecting today hold");p.Release(c);Check(!p.Held(day.AddDays(1)),"explicit resume clears hold");
  c.SkinShuffleMinutes=2;p.Configure(c);Check(p.Session.Remaining==120,"interval edit restarts countdown");c.SkinShuffleJitter=true;for(int i=0;i<50;i++){p.Reset(c);Check(p.Session.Remaining>=108&&p.Session.Remaining<=132,"jitter remains within ten percent");}
  c=new Config{SkinShuffleJitter=false};c.Validate();p=new SkinShufflePlanner(new Random(42));p.Load(null,c);var selected=new List<string>{c.Skin};for(int i=0;i<32;i++){string old=c.Skin,id=p.Next(c);Check(id!=null&&id!=old&&c.SkinShufflePool.Contains(id),"no immediate duplicate or out-of-pool choice");c.Skin=id;p.Applied(c);selected.Add(id);}Check(selected.Take(3).Distinct().Count()==3,"initial current skin counts in first round");for(int i=3;i+3<=selected.Count;i+=3)Check(selected.Skip(i).Take(3).Distinct().Count()==3,"each later shuffle round visits all candidates once");
  var saved=Store.Json.Deserialize<SkinShuffleSession>(Store.Json.Serialize(p.Session));saved.Remaining=71;var restored=new SkinShufflePlanner(new Random(6));restored.Load(saved,c);Check(restored.Session.Remaining==71&&restored.Session.Bag.SequenceEqual(p.Session.Bag),"countdown and remaining round survive restart");restored.HoldToday(day);saved=Store.Json.Deserialize<SkinShuffleSession>(Store.Json.Serialize(restored.Session));restored.Load(saved,c);Check(restored.Held(day),"today hold survives restart");c.SkinShuffleOnStart=true;c.SkinShuffleEnabled=false;Check(restored.StartupChoice(c,day,false)==null,"today hold also blocks startup randomization");restored.Release(c);Check(restored.StartupChoice(c,day,true)==null&&restored.StartupChoice(c,day,false)!=null,"startup works independently and never changes preview pet");
  c.SkinShufflePool=new[]{c.Skin};c.Validate();restored.Configure(c);Check(restored.Next(c)==null,"single current candidate produces no redundant switch");c.SkinShufflePool=new string[0];restored.Configure(c);Check(restored.Next(c)==null,"no candidates produces no switch");restored.Load(new SkinShuffleSession{Remaining=double.NaN,Pool=null,Bag=null,HeldDate="invalid"},c);Check(MusicReactions.Finite(restored.Session.Remaining),"corrupted checkpoint safely resets");Check(SkinShuffleRules.WaitText(25*3600)=="25:00:00","long intervals do not wrap at midnight");
  var incoming=PreferenceReview.Parse(PreferenceTransfer.Export(new Config{SkinShuffleMinutes=35,SkinShufflePool=new[]{SkinShuffleRules.Defaults[1]}},false));Check(incoming.PresentKeys.Contains("SkinShufflePool")&&incoming.Preferences.SkinShuffleMinutes==35&&!incoming.PresentKeys.Any(k=>k.Contains("HeldDate")||k.Contains("Remaining")),"shared preferences carry settings without local timer state");
 }
 static void Boundaries(){
  var b=new SkinShuffleBoundary();Check(!b.Observe("idle",6400,6600,true,false,0)&&!b.Observe("idle",6500,6600,true,false,.1)&&b.Observe("idle",6650,6600,true,false,.25),"idle boundary waits for cycle wrap");Check(!b.Observe("idle",6700,6600,false,false,.3)&&!b.Observe("idle",13210,6600,true,false,1),"blocked interaction discards old boundary");Check(!b.Observe("music-quiet",-1,2400,true,false,2),"sit transition cannot count as quiet loop");Check(!b.Observe("music-quiet",2390,2400,true,false,3)&&b.Observe("music-quiet",2410,2400,true,false,3.25),"quiet music cycle boundary");Check(!b.Observe("music-quiet",500000,2400,true,false,500),"resume after long gap requires fresh observation");b.Reset();Check(!b.Observe("idle",0,6600,true,true,0)&&!b.Observe("idle",0,6600,true,true,1)&&b.Observe("idle",0,6600,true,true,2),"reduced motion switches after stable static idle");
 }
 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);try{Planner();Boundaries();}catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});return 1;}
  var config=new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false,SkinShuffleActions=new string[0],SmoothTransitions=false};Store.Save(config);var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{
   await Task.Delay(1100);((DispatcherTimer)Field(pet,"animation")).Stop();var window=app.Windows.OfType<SettingsWindow>().Single();window.NavigateCategory("外观与互动","随机换装");await Task.Delay(80);window.UpdateStatus();var fold=(Expander)Field(window,"skinShuffleSection");Check(fold.IsExpanded&&fold.IsVisible,"settings search expands shuffle controls");var choices=(Dictionary<string,CheckBox>)Field(window,"skinShuffleChoices");Check(choices.Count==6&&choices.Count(pair=>pair.Value.IsChecked==true)==3&&choices.Where(pair=>pair.Value.IsChecked==true).All(pair=>MusicSprites.Supported(pair.Key)),"six configurable choices with only Q defaults selected");
   var minutes=(TextBox)Field(window,"skinShuffleMinutes");minutes.Text="37";SettingsWindow.Descendants<Button>(window).Single(button=>(string)button.Content=="保存随机间隔").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Store.Load().SkinShuffleMinutes==37,"custom interval saved through actual UI");string normal="kiana-winter-wish";choices[normal].IsChecked=true;Check(Store.Load().SkinShufflePool.Contains(normal),"ordinary outfit can be explicitly included");SettingsWindow.Descendants<Button>(window).Single(button=>(string)button.Content=="只选三套 Q 版").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(pet.Settings.SkinShufflePool.Length==3&&choices[normal].IsChecked==false,"restore Q-only selection synchronizes checkboxes");pet.HoldSkinToday();window.UpdateStatus();Check(((TextBlock)Field(window,"skinShuffleStatus")).Text.Contains("今天固定"),"today hold visible in settings");pet.ResumeSkinShuffle();window.UpdateStatus();window.Capture(Path.Combine(Store.Root,"random-skin-settings.png"));window.Close();
   pet.IsHitTestVisible=false;Set(pet,"hover",false);Set(pet,"interaction",null);Set(pet,"quietActive",false);Set(pet,"menuLayerYielding",false);Set(pet,"displayPending",false);Set(pet,"state","idle");Set(pet,"sleeping",false);Check((string)Call(pet,"SkinShuffleBlockReason")=="","idle runtime eligible after settings close");
   foreach(var field in new[]{"pressed","dragging","sleeping","quietActive","sessionLocked","manualHidden","menuLayerYielding"}){Set(pet,field,true);Check(((string)Call(pet,"SkinShuffleBlockReason")).Length>0,"runtime protection: "+field);Set(pet,field,false);}pet.StartFocus(false);Check(((string)Call(pet,"SkinShuffleBlockReason")).Contains("专注"),"focus session blocks random skin changes");pet.ResetFocus();pet.Settings.LinkChatGPT=true;pet.Link.Current.Connected=true;pet.Link.Current.At=DateTime.UtcNow;foreach(string active in new[]{"running","waiting","failed","unknown"}){pet.Link.Current.State=active;Check(((string)Call(pet,"SkinShuffleBlockReason")).Contains("GPT"),"GPT state prevents shuffle: "+active);}pet.Settings.LinkChatGPT=false;pet.Link.Current.Connected=false;pet.Link.Current.State="idle";
   double now=((System.Diagnostics.Stopwatch)Field(pet,"clock")).Elapsed.TotalSeconds;Set(pet,"state","music-quiet");Set(pet,"stateAt",now-20);Set(pet,"drawnMusicState","music-quiet");Set(pet,"musicRising",false);pet.Settings.MusicEnabled=true;pet.Settings.MusicChorusEnabled=false;pet.Music.Current=new MusicState{Connected=true,Playing=true,Id="1",Title="Synthetic music",HasPosition=false};Call(pet,"DrawAnimation",20000d);var bounds=new System.Windows.Interop.WindowInteropHelper(pet).Handle;double stateAt=(double)Field(pet,"stateAt"),width=pet.Width,height=pet.Height;var bridge=pet.Link;var music=pet.Music;var planner=Field(pet,"musicReactionPlanner");var pollInterval=((DispatcherTimer)Field(pet,"poll")).Interval;var musicInterval=((DispatcherTimer)Field(pet,"musicTimer")).Interval;
   Call(pet,"ChooseMusicReaction",now-10,true);Call(pet,"ChooseMusicReaction",now,true);var started=Field(planner,"started");var entered=Field(planner,"enteredAt");string target=SkinShuffleRules.Defaults.First(id=>id!=pet.Settings.Skin);pet.Settings.ToolbarColorSource="outfit";pet.Settings.ToolbarStyle="tricolor";pet.Settings.ToolbarFollowMusic=false;Call(pet,"UpdateToolbarTheme",now);var oldColors=string.Join("/",((System.Windows.Media.Color[])Field(pet,"toolbarColors")).Select(color=>color.ToString()));string before=Bounds(bounds);var oldImage=((Image)Field(pet,"sprite")).Source;
   Check((bool)Call(pet,"ApplyAutomaticSkin",target,now),"automatic Q switch loads real assets");Check(pet.CurrentAction=="music-quiet"&&(double)Field(pet,"stateAt")==stateAt&&Field(pet,"interaction")==null,"automatic switch keeps music phase and does not wave");Check(Bounds(bounds)==before&&pet.Width==width&&pet.Height==height,"automatic switch preserves physical bounds and size");Check(ReferenceEquals(pet.Link,bridge)&&ReferenceEquals(pet.Music,music)&&ReferenceEquals(Field(pet,"musicReactionPlanner"),planner)&&Equals(Field(planner,"started"),started)&&Equals(Field(planner,"enteredAt"),entered),"automatic switch preserves providers and music session timeline");Check(((DispatcherTimer)Field(pet,"poll")).Interval==pollInterval&&((DispatcherTimer)Field(pet,"musicTimer")).Interval==musicInterval,"automatic switch does not reset connection polling");Check(!ReferenceEquals(((Image)Field(pet,"sprite")).Source,oldImage)&&(int)Field(pet,"lastFrame")>=1400,"first composed frame uses the new outfit and current music pose");Call(pet,"UpdateToolbarTheme",now);Check(oldColors!=string.Join("/",((System.Windows.Media.Color[])Field(pet,"toolbarColors")).Select(color=>color.ToString())),"outfit-following toolbar palette refreshes after automatic skin change");Check(pet.Settings.GPTConnectionMode=="cdp"&&pet.Settings.MusicConnectionMode=="cdp","original connection selections retained");
   pet.Music.Current.HasPosition=true;pet.Music.Current.Position=20;pet.Settings.MusicSongPreferences=new[]{new SongMusicPreference{Id="1",Start=0,End=100}};Check(((string)Call(pet,"SkinShuffleBlockReason")).Contains("副歌"),"known chorus blocks even a quiet chorus pose");pet.Music.Current.HasPosition=false;pet.Settings.MusicSongPreferences=new SongMusicPreference[0];
   string bad="kiana-winter-wish",asset=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",bad+".png"),backup=asset+".test-backup";string skinBefore=pet.Settings.Skin;Check(Path.GetFullPath(asset).Contains(Path.Combine(".local","tests")),"failure fixture only touches isolated asset copy");File.Move(asset,backup);try{Check(!(bool)Call(pet,"ApplyAutomaticSkin",bad,now)&&pet.Settings.Skin==skinBefore&&pet.CurrentAction=="music-quiet","missing candidate asset restores previous outfit and music pose");}finally{File.Move(backup,asset);}
   pet.Settings.SkinShufflePool=SkinShuffleRules.Allowed.ToArray();Check(((string)Call(pet,"SkinShuffleBlockReason")).Contains("普通版"),"mixed regular/Q pool waits for ordinary idle during music");pet.Settings.SkinShufflePool=SkinShuffleRules.Defaults.ToArray();pet.Settings.SkinShuffleJitter=false;pet.UpdateSkinShuffleSettings();var shuffle=(SkinShufflePlanner)Field(pet,"skinShuffle");shuffle.Session.Remaining=0;string manual=SkinShuffleRules.Defaults.First(id=>id!=pet.Settings.Skin);pet.SelectSkin(manual);Check(shuffle.Session.Remaining==37*60&&Equals(Field(pet,"interaction"),"waving"),"manual outfit selection retains greeting and restarts interval");pet.HoldSkinToday();var checkpoint=Store.Json.Deserialize<SkinShuffleSession>(File.ReadAllText(Path.Combine(Store.Root,"skin-shuffle-session.json")));Check(checkpoint.HeldDate==SkinShuffleRules.Day(DateTime.Now),"today hold saved independently of exported preferences");pet.ResumeSkinShuffle();passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{Store.Atomic("result.json",new{passed,checks,names});foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);return passed?0:1;
 }
